// Precompile bindings for balance queries and transfers
sol! {
    #[allow(missing_docs)]
    #[sol(rpc)]
    interface IStakingV2 {
        function getStake(bytes32 hotkey, bytes32 coldkey, uint256 netuid) external view returns (uint256);
        function transferStake(bytes32 destination_coldkey, bytes32 hotkey, uint256 origin_netuid, uint256 destination_netuid, uint256 amount) external payable;
    }

    #[allow(missing_docs)]
    #[sol(rpc)]
    interface IAddressMapping {
        function addressMapping(address evmAddress) external view returns (bytes32);
    }

    #[allow(missing_docs)]
    #[sol(rpc)]
    interface IBalanceTransfer {
        function transfer(bytes32 data) external payable;
    }
}

const STAKING_V2_PRECOMPILE: Address = address!("0x0000000000000000000000000000000000000805");
const ADDRESS_MAPPING_PRECOMPILE: Address = address!("0x000000000000000000000000000000000000080C");
const BALANCE_TRANSFER_PRECOMPILE: Address = address!("0x0000000000000000000000000000000000000800");

/// Derive an EVM address from a hex private key string.
pub fn address_from_private_key(private_key: &str) -> Result<Address, anyhow::Error> {
    let signer: PrivateKeySigner = private_key.parse()?;
    Ok(signer.address())
}

/// Get the TAO (wei) balance of an EVM address
pub async fn get_tao_balance(
    address: Address,
    network_config: &CollateralNetworkConfig,
) -> Result<U256, anyhow::Error> {
    let provider = ProviderBuilder::new()
        .connect(&network_config.rpc_url)
        .await?;
    let balance = provider.get_balance(address).await?;
    Ok(balance)
}

/// Get the alpha staked balance for a coldkey under a hotkey on a netuid.
/// Returns RAO (1e9 = 1 alpha).
pub async fn get_alpha_balance(
    alpha_hotkey: [u8; 32],
    coldkey: [u8; 32],
    netuid: u16,
    network_config: &CollateralNetworkConfig,
) -> Result<U256, anyhow::Error> {
    let provider = ProviderBuilder::new()
        .connect(&network_config.rpc_url)
        .await?;
    let staking = IStakingV2::new(STAKING_V2_PRECOMPILE, provider);
    let stake = staking
        .getStake(
            FixedBytes::from_slice(&alpha_hotkey),
            FixedBytes::from_slice(&coldkey),
            U256::from(netuid),
        )
        .call()
        .await?;
    Ok(stake)
}

/// Send TAO from the EVM wallet to a substrate (SS58) destination.
/// `destination` is the 32-byte public key decoded from the SS58 address.
/// `amount_wei` is the TAO amount in wei (1e18 = 1 TAO).
pub async fn send_tao(
    private_key: &str,
    destination: [u8; 32],
    amount_wei: U256,
    network_config: &CollateralNetworkConfig,
) -> Result<(), anyhow::Error> {
    let mut signer: PrivateKeySigner = private_key.parse()?;
    signer.set_chain_id(Some(network_config.chain_id));

    let provider = ProviderBuilder::new()
        .wallet(signer)
        .connect(&network_config.rpc_url)
        .await?;

    let precompile = IBalanceTransfer::new(BALANCE_TRANSFER_PRECOMPILE, provider);
    let tx = precompile
        .transfer(FixedBytes::from_slice(&destination))
        .value(amount_wei)
        .send()
        .await
        .map_err(|e| decode_contract_revert(e.into()))?;
    tx.get_receipt().await?;
    Ok(())
}

/// Send alpha from the EVM wallet to a substrate (SS58) destination coldkey.
/// This calls `transferStake` on the StakingV2 precompile, transferring alpha
/// ownership from the caller's coldkey to the destination coldkey.
/// `amount_rao` is the alpha amount in RAO (1e9 = 1 alpha).
pub async fn send_alpha(
    private_key: &str,
    destination_coldkey: [u8; 32],
    hotkey: [u8; 32],
    netuid: u16,
    amount_rao: U256,
    network_config: &CollateralNetworkConfig,
) -> Result<(), anyhow::Error> {
    let mut signer: PrivateKeySigner = private_key.parse()?;
    signer.set_chain_id(Some(network_config.chain_id));

    let provider = ProviderBuilder::new()
        .wallet(signer)
        .connect(&network_config.rpc_url)
        .await?;

    let staking = IStakingV2::new(STAKING_V2_PRECOMPILE, provider);
    let netuid_u256 = U256::from(netuid);
    let tx = staking
        .transferStake(
            FixedBytes::from_slice(&destination_coldkey),
            FixedBytes::from_slice(&hotkey),
            netuid_u256,
            netuid_u256,
            amount_rao,
        )
        .send()
        .await
        .map_err(|e| decode_contract_revert(e.into()))?;
    tx.get_receipt().await?;
    Ok(())
}

/// Derive the Substrate mirror coldkey (AccountId32) from an EVM address
/// via the AddressMapping precompile at 0x...080C.
pub async fn derive_coldkey(
    evm_address: Address,
    network_config: &CollateralNetworkConfig,
) -> Result<[u8; 32], anyhow::Error> {
    let provider = ProviderBuilder::new()
        .connect(&network_config.rpc_url)
        .await?;
    let mapping = IAddressMapping::new(ADDRESS_MAPPING_PRECOMPILE, provider);
    let result = mapping.addressMapping(evm_address).call().await?;
    Ok(result.into())
}

#[cfg(test)]
mod decode_tests {
    use super::*;
    use alloy_sol_types::SolError;

    #[test]
    fn test_decode_known_error() {
        let encoded = SolError::abi_encode(&CollateralUpgradeable::NodeNotOwned {});
        let hex = alloy_primitives::hex::encode(&encoded);
        let result = decode_revert_data(&hex);
        assert!(result.unwrap().contains("different miner"));
    }

    #[test]
    fn test_decode_with_0x_prefix() {
        let encoded = SolError::abi_encode(&CollateralUpgradeable::AmountZero {});
        let hex = format!("0x{}", alloy_primitives::hex::encode(&encoded));
        let result = decode_revert_data(&hex);
        assert!(result.unwrap().contains("greater than zero"));
    }

    #[test]
    fn test_decode_contract_revert_rewrites_message() {
        let hex = alloy_primitives::hex::encode(SolError::abi_encode(
            &CollateralUpgradeable::AmountZero {},
        ));
        let err = anyhow::anyhow!("error code -32603: revert, data: \"0x{hex}\"");
        let decoded = decode_contract_revert(err);
        assert!(decoded.to_string().contains("greater than zero"));
        assert!(!decoded.to_string().contains("0x"));
    }

    #[test]
    fn test_unknown_selector_returns_none() {
        assert!(decode_revert_data("deadbeef").is_none());
    }

    #[test]
    fn test_decode_contract_revert_passes_through_non_revert() {
        let original = "connection refused";
        let err = anyhow::anyhow!(original.to_string());
        let result = decode_contract_revert(err);
        assert_eq!(result.to_string(), original);
    }
}
